        "Closed": "select CASE WHEN  hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN  closedby.assignee_ is not null THEN clsuser.email_ ELSE ''Auto Closed'' END ELSE null END as \\"Closed By\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END  as \\"VPA\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''account''->>''vcexternalaccountid'' END  as \\"Account\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''customer''->>''vcexternalcustid'' END  as \\"Customer\\", hiproinst.end_time_  as  \\"Closed Date\\", CASE WHEN  hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END as \\"Stage\\", task.assignee_ as \\"Claimed By\\", hiproinst.start_time_  as  \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' then ''Closed'' WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN task.assignee_ is not null THEN oplog.time_ ELSE null END  as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" from camunda.act_hi_procinst hiproinst full outer join camunda.act_re_procdef pdef on pdef.id_ = hiproinst.proc_def_id_ full outer join camunda.act_ru_task task on task.proc_inst_id_ = hiproinst.proc_inst_id_ full outer join camunda.act_hi_detail oplog on oplog.id_ = (select id_ from camunda.act_hi_detail where proc_inst_id_ = task.proc_inst_id_ and name_ = ''userActivity'' order by time_ desc limit 1) full outer join camunda.act_hi_taskinst closedby on closedby.id_ = (select id_ from camunda.act_hi_taskinst where proc_inst_id_ = hiproinst.proc_inst_id_ order by end_time_ desc limit 1) left join camunda.act_id_user clsuser on clsuser.id_ = closedby.assignee_ full outer join camunda.act_hi_varinst payer on payer.proc_inst_id_ = hiproinst.proc_inst_id_ and payer.name_ = ''payer'' full outer join camunda.act_hi_varinst payee on payee.proc_inst_id_ = hiproinst.proc_inst_id_ and payee.name_ = ''payee'' full outer join camunda.act_hi_varinst  TransactionAmount on TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' full outer join camunda.act_hi_varinst  TicketID on TicketID.proc_inst_id_ = hiproinst.proc_inst_id_ and TicketID.name_ = ''TicketID'' full outer join camunda.act_hi_varinst  Txn on Txn.proc_inst_id_ = hiproinst.proc_inst_id_ and Txn.name_ = ''Transaction'' full outer join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ full outer join camunda.act_hi_varinst Alert on Alert.proc_inst_id_ = hiproinst.proc_inst_id_ and Alert.name_ = ''Alert'' where cast(hiproinst.start_time_ as date) between cast(:StartDate as date) and cast(:EndDate as date) and hiproinst.state_ = ''COMPLETED'' and hiproinst.proc_def_key_ = :CaseType and hiproinst.tenant_id_= :tenantidstr"
